import openpyxl
wb = openpyxl.load_workbook('1_51661_answer_template_5813_input.xlsx', data_only=False)
wb_ans = openpyxl.load_workbook('/mnt/hhq/data/answer_files/1_51661_answer.xlsx', data_only=False)

# Full style comparison for all cells (including borders/fonts/fills/number formats)
def style_tuple(cell):
    return (cell.number_format, cell._style, cell.data_type)

diffs = 0
for ws_in in wb_in.worksheets:
    ws_ans = wb_ans[ws_in.title]
    for r in range(1, max(ws_in.max_row, ws_ans.max_row)+1):
        for c in range(1, max(ws_in.max_column, ws_ans.max_column)+1):
            ci = ws_in.cell(row=r, column=c)
            ca = ws_ans.cell(row=r, column=c)
            if style_tuple(ci) != style_tuple(ca):
                print(f'STYLE DIFF {ws_in.title}!{ci.coordinate}: in={style_tuple(ci)} ans={style_tuple(ca)}')
                diffs += 1
print('style diffs:', diffs)
